class Solution {
    public long maxBalancedSubsequenceSum(int[] nums) {
        int n = nums.length;
        long[] keys = new long[n];
        for (int i = 0; i < n; i++) keys[i] = (long) nums[i] - i;
        long[] sortedKeys = keys.clone();
        Arrays.sort(sortedKeys);
        int m = 0;
        for (int i = 0; i < n; i++) {
            if (i == 0 || sortedKeys[i] != sortedKeys[i - 1]) {
                sortedKeys[m++] = sortedKeys[i];
            }
        }
        long[] bit = new long[m + 1];
        Arrays.fill(bit, Long.MIN_VALUE / 2);
        long ans = Long.MIN_VALUE;
        for (int i = 0; i < n; i++) {
            int r = Arrays.binarySearch(sortedKeys, 0, m, keys[i]) + 1;
            long prev = Long.MIN_VALUE / 2;
            for (int idx = r; idx > 0; idx -= idx & (-idx)) prev = Math.max(prev, bit[idx]);
            long curr = Math.max((long) nums[i], prev + nums[i]);
            ans = Math.max(ans, curr);
            for (int idx = r; idx <= m; idx += idx & (-idx)) bit[idx] = Math.max(bit[idx], curr);
        }
        return ans;
    }
}

