var maxBalancedSubsequenceSum = function(nums) {
    const n = nums.length;
    const keys = new Array(n);
    for (let i = 0; i < n; i++) keys[i] = BigInt(nums[i] - i);
    const sortedKeys = Array.from(new Set(keys)).sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
    const m = sortedKeys.length;
    const bit = new BigInt64Array(m + 1).fill(-1000000000000000000n);
    function query(idx) {
        let res = -1000000000000000000n;
        for (; idx > 0; idx -= idx & (-idx)) {
            if (bit[idx] > res) res = bit[idx];
        }
        return res;
    }
    function update(idx, val) {
        for (; idx <= m; idx += idx & (-idx)) {
            if (val > bit[idx]) bit[idx] = val;
        }
    }
    let ans = -1000000000000000000n;
    for (let i = 0; i < n; i++) {
        let lo = 0, hi = m - 1, r = 1;
        while (lo <= hi) {
            const mid = (lo + hi) >> 1;
            if (sortedKeys[mid] >= keys[i]) {
                r = mid + 1;
                hi = mid - 1;
            } else lo = mid + 1;
        }
        const prev = query(r);
        const numVal = BigInt(nums[i]);
        const curr = (numVal > prev + numVal) ? numVal : prev + numVal;
        if (curr > ans) ans = curr;
        update(r, curr);
    }
    return Number(ans);
};
